using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var storage = new DiskBasedReportingStorage(Path.Combine("TestResults", "eval-report"));
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator(),
        };

        s_reportingConfiguration = new ReportingConfiguration(evaluators, storage);
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        await using var appHost =
            await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(
            messages,
            response,
            additionalContext:
            [
                new EvaluationContext("grounding", "The capital of France is Paris.")
            ]);

        scenario.AssertAllMetricsPassed();
    }
}

